import { GLOBALTYPES } from './globalTypes';
import { postDataAPI } from '../../utils/fetchData'; // Correctly import the new API utility
import { valid } from '../../utils/valid'

// This is the register action called by your RegisterAdmin component.
// It now has more robust error handling.
export const register = (data) => async (dispatch) => {
    const check = valid(data);
    if (check.errLength > 0) {
        return dispatch({ type: GLOBALTYPES.ALERT, payload: check.errMsg });
    }

    try {
        dispatch({ type: GLOBALTYPES.ALERT, payload: { loading: true } });

        const res = await postDataAPI('register', data);

        dispatch({
            type: GLOBALTYPES.AUTH,
            payload: {
                token: res.data.access_token,
                user: res.data.user
            }
        });

        localStorage.setItem('firstLogin', true);

        dispatch({
            type: GLOBALTYPES.ALERT,
            payload: {
                success: res.data.msg
            }
        });

    } catch (err) {
        dispatch({
            type: GLOBALTYPES.ALERT,
            payload: {
                // Provides a much better error message to the user.
                error: err.response?.data?.msg || "An unexpected error occurred."
            }
        });
    }
};

// --- I have also included updated versions of your other auth actions ---
// --- to ensure consistency and prevent similar errors. ---

export const login = (data) => async (dispatch) => {
    try {
        dispatch({ type: GLOBALTYPES.ALERT, payload: { loading: true } });

        const res = await postDataAPI('login', data);

        dispatch({
            type: GLOBALTYPES.AUTH,
            payload: {
                token: res.data.access_token,
                user: res.data.user
            }
        });

        localStorage.setItem('firstLogin', true);

        dispatch({
            type: GLOBALTYPES.ALERT,
            payload: {
                success: res.data.msg
            }
        });

    } catch (err) {
        dispatch({
            type: GLOBALTYPES.ALERT,
            payload: {
                error: err.response?.data?.msg || "An unexpected error occurred."
            }
        });
    }
};

export const refreshToken = () => async (dispatch) => {
    const firstLogin = localStorage.getItem('firstLogin');
    if (firstLogin) {
        dispatch({ type: GLOBALTYPES.ALERT, payload: { loading: true } });
        try {
            const res = await postDataAPI('refresh_token');
            dispatch({
                type: GLOBALTYPES.AUTH,
                payload: {
                    token: res.data.access_token,
                    user: res.data.user
                }
            });
            dispatch({ type: GLOBALTYPES.ALERT, payload: {} });
        } catch (err) {
            dispatch({
                type: GLOBALTYPES.ALERT,
                payload: {
                    error: err.response?.data?.msg || "An unexpected error occurred."
                }
            });
        }
    }
};

export const logout = () => async (dispatch) => {
    try {
        localStorage.removeItem('firstLogin');
        await postDataAPI('logout');
        window.location.href = "/";
    } catch (err) {
        dispatch({
            type: GLOBALTYPES.ALERT,
            payload: {
                error: err.response?.data?.msg || "An unexpected error occurred."
            }
        });
    }
};
